package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Config group is "combat-vitals" and must never be renamed without a migration —
 * renaming silently resets everyone's saved settings.
 */
@ConfigGroup(CombatVitalsConfig.GROUP)
public interface CombatVitalsConfig extends Config
{
	String GROUP = "combat-vitals";

	@ConfigSection(
		name = "Display",
		description = "What the readout shows and where",
		position = 0
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Targets",
		description = "Which opponents the readout appears for",
		position = 1
	)
	String targetSection = "targets";

	@ConfigSection(
		name = "Advanced",
		description = "Timeouts and diagnostics",
		position = 2,
		closedByDefault = true
	)
	String advancedSection = "advanced";

	@ConfigItem(
		keyName = "showPanel",
		name = "Show panel",
		description = "Draw the opponent's health in a corner panel, like the stock plugin.",
		section = displaySection,
		position = 0
	)
	default boolean showPanel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOverhead",
		name = "Show over target",
		description = "Draw the opponent's health above them in the world.",
		section = displaySection,
		position = 1
	)
	default boolean showOverhead()
	{
		return true;
	}

	@ConfigItem(
		keyName = "displayMode",
		name = "Display",
		description = "Show hitpoints, a percentage, or both.",
		section = displaySection,
		position = 2
	)
	default DisplayMode displayMode()
	{
		return DisplayMode.BOTH;
	}

	@ConfigItem(
		keyName = "percentageDecimals",
		name = "Decimal percentage",
		description = "Show one decimal place on percentages.",
		section = displaySection,
		position = 3
	)
	default boolean percentageDecimals()
	{
		return false;
	}

	@ConfigItem(
		keyName = "colourGradient",
		name = "Colour by health",
		description = "Fade the text from green to red as the target loses health.",
		section = displaySection,
		position = 8
	)
	default boolean colourGradient()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overheadPosition",
		name = "Overhead position",
		description = "Where above the target the text sits. Large NPCs often read better on Bottom.",
		section = displaySection,
		position = 5
	)
	default OverheadPosition overheadPosition()
	{
		return OverheadPosition.TOP;
	}

	@Alpha
	@ConfigItem(
		keyName = "healthFullColour",
		name = "Colour at full",
		description = "Colour of the readout at full health, used when Colour by health is on.",
		section = displaySection,
		position = 9
	)
	default Color healthFullColour()
	{
		return new Color(0, 146, 54, 230);
	}

	@Alpha
	@ConfigItem(
		keyName = "healthMidColour",
		name = "Colour at half",
		description = "Colour the readout passes through at half health.",
		section = displaySection,
		position = 10
	)
	default Color healthMidColour()
	{
		return new Color(255, 193, 7, 230);
	}

	@Alpha
	@ConfigItem(
		keyName = "healthLowColour",
		name = "Colour at empty",
		description = "Colour of the readout as health approaches zero.",
		section = displaySection,
		position = 11
	)
	default Color healthLowColour()
	{
		return new Color(199, 26, 26, 230);
	}

	@ConfigItem(
		keyName = "overheadStyle",
		name = "Style",
		description =
			"Bar behind text draws a health bar sized to fit the text, carrying the colour so the text "
				+ "can stay white. Text above health bar lifts the text clear of the game's own bar "
				+ "instead. Text only draws coloured text where it falls, which will overlap the "
				+ "game's bar.",
		section = displaySection,
		position = 4
	)
	default OverheadStyle overheadStyle()
	{
		return OverheadStyle.BAR;
	}

	@Alpha
	@ConfigItem(
		keyName = "barBackground",
		name = "Bar background",
		description =
			"Colour behind the health fill, used by the Bar behind text style. Opaque by default so "
				+ "the game's own health bar does not show through it. Lower the alpha to let it "
				+ "show again.",
		section = displaySection,
		position = 7
	)
	default Color barBackground()
	{
		return Color.BLACK;
	}

	@Range(min = -200, max = 200)
	@ConfigItem(
		keyName = "overheadOffset",
		name = "Overhead offset",
		description = "Extra height in pixels, applied after the position above.",
		section = displaySection,
		position = 6
	)
	default int overheadOffset()
	{
		return 0;
	}


	@ConfigItem(
		keyName = "showOwnHealth",
		name = "Show your own health",
		description =
			"Draw your own health over your character while you are engaged, in the same style as your "
				+ "opponent's. Taken from the hitpoints orb, so it is exact rather than recovered.",
		section = targetSection,
		position = 4
	)
	default boolean showOwnHealth()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showForNpcs",
		name = "NPC targets",
		description = "Show the readout when fighting NPCs.",
		section = targetSection,
		position = 0
	)
	default boolean showForNpcs()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showForPlayers",
		name = "Player targets",
		description = "Show the readout when fighting other players.",
		section = targetSection,
		position = 1
	)
	default boolean showForPlayers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overheadForPlayers",
		name = "Draw over players",
		description = "Draw over player targets as well as NPCs. Turn off to keep players in the panel only.",
		section = targetSection,
		position = 2
	)
	default boolean overheadForPlayers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPlayerHitpoints",
		name = "Look up player hitpoints",
		description =
			"Fetch the opponent's Hitpoints level from the hiscores so their health can be shown as a "
				+ "number rather than a percentage. One lookup per opponent, cached. Sends their display "
				+ "name to Jagex's hiscores service. The stock Opponent Information plugin does this with "
				+ "no way to turn it off.",
		section = targetSection,
		position = 3
	)
	default boolean showPlayerHitpoints()
	{
		return true;
	}

	@Range(min = 1, max = 60)
	@ConfigItem(
		keyName = "showStatComparison",
		name = "Stat comparison panel",
		description =
			"Compare your combat stats against a player opponent's, in the panel. Reads the same "
				+ "cached hiscores result as the hitpoints lookup, so it costs no extra request.",
		section = targetSection,
		position = 5
	)
	default boolean showStatComparison()
	{
		return false;
	}

	@ConfigItem(
		keyName = "opponentTimeout",
		name = "Opponent timeout (s)",
		description = "How long the readout stays up after combat ends. The stock plugin fixes this at 5.",
		section = advancedSection,
		position = 0
	)
	default int opponentTimeout()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "hideWhenHpHud",
		name = "Hide behind boss HP bar",
		description = "Stand down when the game's own boss health bar is already showing this target.",
		section = advancedSection,
		position = 1
	)
	default boolean hideWhenHpHud()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideWhenStockEnabled",
		name = "Hide panel if stock plugin is on",
		description =
			"Hide this plugin's panel while Opponent Information is enabled, so the two do not draw "
				+ "over each other. The overhead text is unaffected.",
		section = advancedSection,
		position = 2
	)
	default boolean hideWhenStockEnabled()
	{
		return true;
	}

}

package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws the readout over the target itself, which is the thing the stock
 * plugin cannot do.
 */
class CombatVitalsOverheadOverlay extends Overlay
{
	/** Space between the text and the edge of the bar behind it. */
	private static final int PAD_X = 4;
	private static final int PAD_Y = 2;

	private static final Color BAR_BORDER = new Color(0, 0, 0, 200);

	/**
	 * Height cleared when lifting the text above the game's own health bar.
	 * The bar's position is not exposed by the API, so this is a fixed clearance
	 * that puts the text above it; the offset setting fine-tunes from there.
	 */
	private static final int BAR_CLEARANCE = 34;

	private final CombatVitalsPlugin plugin;
	private final CombatVitalsConfig config;

	@Inject
	CombatVitalsOverheadOverlay(CombatVitalsPlugin plugin, CombatVitalsConfig config)
	{
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverhead())
		{
			return null;
		}

		final CombatVitalsPlugin.Readout opponent = plugin.getReadout();
		if (opponent != null && (opponent.isNpc() || config.overheadForPlayers()))
		{
			draw(graphics, opponent);
		}

		// Both sides in one visual language. Getting your own health from some
		// other plugin would render it in a different style beside your
		// opponent's, which is the main reason this belongs here.
		draw(graphics, plugin.getSelfReadout());
		return null;
	}

	private void draw(Graphics2D graphics, CombatVitalsPlugin.Readout readout)
	{
		if (readout == null)
		{
			return;
		}

		final String text = HealthReadout.text(readout.getRange(), readout.getMaxHealth(),
			readout.getRatio(), readout.getScale(), config.displayMode(), config.percentageDecimals(),
			readout.getExactHealth());
		if (text == null)
		{
			return;
		}

		final Actor actor = readout.getActor();
		final Point location = actor.getCanvasTextLocation(graphics, text, zOffset(actor));
		if (location == null)
		{
			return;
		}

		final double fraction = HealthReadout.fraction(readout.getRatio(), readout.getScale(),
			readout.getExactHealth(), readout.getMaxHealth());

		if (config.overheadStyle() == OverheadStyle.BAR)
		{
			drawBar(graphics, location, text, fraction);

			// White on a filled bar. Colouring the text as well as the bar makes
			// the two fight each other — red text on a green bar is the worst
			// case and the reason this style exists.
			OverlayUtil.renderTextLocation(graphics, location, text, Color.WHITE);
			return;
		}

		final Color colour = config.colourGradient() ? gradient(fraction) : Color.WHITE;
		OverlayUtil.renderTextLocation(graphics, location, text, colour);
	}

	/**
	 * A bar exactly as wide as the text it sits behind. The game's own bar is a
	 * fixed handful of pixels and the readout is always wider, so sizing to the
	 * text is what makes the two legible together instead of overlapping.
	 */
	private void drawBar(Graphics2D graphics, Point location, String text, double fraction)
	{
		final FontMetrics metrics = graphics.getFontMetrics();
		final int textWidth = metrics.stringWidth(text);

		final int x = location.getX() - PAD_X;
		final int y = location.getY() - metrics.getAscent() - PAD_Y;
		final int width = textWidth + PAD_X * 2;
		final int height = metrics.getAscent() + metrics.getDescent() + PAD_Y * 2;

		// Opaque by default: a translucent background lets the game's own health
		// bar show through and the two read as one smeared bar.
		graphics.setColor(config.barBackground());
		graphics.fillRect(x, y, width, height);

		final int filled = (int) Math.round(width * Math.max(0, Math.min(1, fraction)));
		if (filled > 0)
		{
			graphics.setColor(config.colourGradient() ? gradient(fraction) : config.healthFullColour());
			graphics.fillRect(x, y, filled, height);
		}

		graphics.setColor(BAR_BORDER);
		graphics.drawRect(x, y, width, height);
	}

	private Color gradient(double fraction)
	{
		return HealthReadout.colour(fraction,
			config.healthFullColour(), config.healthMidColour(), config.healthLowColour());
	}

	/**
	 * Height above the actor's base. A large NPC's own name plate and the
	 * top-screen boss bar both crowd the top, which is why this is adjustable
	 * rather than fixed.
	 */
	private int zOffset(Actor actor)
	{
		final int logicalHeight = Math.max(0, actor.getLogicalHeight());

		final int base;
		switch (config.overheadPosition())
		{
			case MIDDLE:
				base = logicalHeight / 2;
				break;
			case BOTTOM:
				base = 0;
				break;
			case TOP:
			default:
				base = logicalHeight;
				break;
		}

		// ABOVE_BAR has to clear the game's bar; the other styles either cover it
		// or deliberately sit where it falls.
		final int clearance = config.overheadStyle() == OverheadStyle.ABOVE_BAR ? BAR_CLEARANCE : 0;

		return base + clearance + config.overheadOffset();
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

/**
 * The corner panel, equivalent to the stock plugin's. It reads the tick
 * snapshot and does no work of its own beyond laying out text.
 */
class CombatVitalsPanelOverlay extends OverlayPanel
{
	/** The same seven the base client compares, in the same order. */
	private static final HiscoreSkill[] COMBAT_SKILLS = {
		HiscoreSkill.ATTACK,
		HiscoreSkill.STRENGTH,
		HiscoreSkill.DEFENCE,
		HiscoreSkill.HITPOINTS,
		HiscoreSkill.RANGED,
		HiscoreSkill.MAGIC,
		HiscoreSkill.PRAYER,
	};

	private static final Skill[] OWN_SKILLS = {
		Skill.ATTACK,
		Skill.STRENGTH,
		Skill.DEFENCE,
		Skill.HITPOINTS,
		Skill.RANGED,
		Skill.MAGIC,
		Skill.PRAYER,
	};

	private static final Color AHEAD = new Color(0, 200, 83);
	private static final Color BEHIND = new Color(220, 60, 60);

	private final CombatVitalsPlugin plugin;
	private final CombatVitalsConfig config;
	private final Client client;

	@Inject
	CombatVitalsPanelOverlay(CombatVitalsPlugin plugin, CombatVitalsConfig config, Client client)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.client = client;

		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_HIGH);
		panelComponent.setBorder(new Rectangle(2, 2, 2, 2));
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "Combat Vitals overlay");
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showPanel())
		{
			return null;
		}

		// Two panels stacked in the same corner reads as a broken plugin, so
		// stand down rather than draw over the stock one.
		if (config.hideWhenStockEnabled() && plugin.stockPluginEnabled())
		{
			return null;
		}

		final CombatVitalsPlugin.Readout readout = plugin.getReadout();
		if (readout == null)
		{
			return null;
		}

		final String text = HealthReadout.text(readout.getRange(), readout.getMaxHealth(),
			readout.getRatio(), readout.getScale(), config.displayMode(), config.percentageDecimals(),
			readout.getExactHealth());
		if (text == null)
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(readout.getName())
			.build());

		final LineComponent.LineComponentBuilder line = LineComponent.builder().left(text);
		if (config.colourGradient())
		{
			line.leftColor(HealthReadout.colour(
				HealthReadout.fraction(readout.getRatio(), readout.getScale(),
					readout.getExactHealth(), readout.getMaxHealth()),
				config.healthFullColour(), config.healthMidColour(), config.healthLowColour()));
		}
		panelComponent.getChildren().add(line.build());

		addStatComparison(readout);

		return super.render(graphics);
	}

	/**
	 * Your combat stats against theirs, from the hiscores result already fetched
	 * for the hitpoints lookup. No second request: the same cache entry answers
	 * both, which is why this costs nothing beyond the panel space.
	 */
	private void addStatComparison(CombatVitalsPlugin.Readout readout)
	{
		if (!config.showStatComparison())
		{
			return;
		}

		final HiscoreResult hiscore = readout.getHiscore();
		if (hiscore == null)
		{
			return;
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Skill")
			.right("You / Them")
			.build());

		for (int i = 0; i < COMBAT_SKILLS.length; i++)
		{
			final net.runelite.client.hiscore.Skill theirs = hiscore.getSkill(COMBAT_SKILLS[i]);

			// Unranked in a skill comes back non-positive. Skipping the row is
			// honest; showing a zero would read as a level.
			if (theirs == null || theirs.getLevel() <= 0)
			{
				continue;
			}

			final int mine = client.getRealSkillLevel(OWN_SKILLS[i]);
			final int level = theirs.getLevel();

			panelComponent.getChildren().add(LineComponent.builder()
				.left(COMBAT_SKILLS[i].getName())
				.right(mine + " / " + level)
				.rightColor(mine == level ? Color.WHITE : (mine > level ? AHEAD : BEHIND))
				.build());
		}
	}
}

package com.vinnyvangogh.combatvitals;

import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ParamID;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.NPCManager;
import net.runelite.client.hiscore.HiscoreEndpoint;
import net.runelite.client.hiscore.HiscoreManager;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

/**
 * Combat Vitals — a standalone replacement for the stock Opponent Information
 * plugin, with overhead rendering.
 *
 * The readout is rebuilt once per game tick and published as an immutable
 * snapshot. The overlays render whatever the latest snapshot holds and compute
 * nothing themselves, because they run every frame and the underlying health
 * bar only changes on a tick.
 */
@Slf4j
@PluginDescriptor(
	name = "Combat Vitals",
	description = "Health for your target and for you, drawn over the target or in a panel",
	tags = {"combat", "vitals", "health", "hitpoints", "hp", "overlay", "overhead", "opponent", "pvp", "pvm"}
)
public class CombatVitalsPlugin extends Plugin
{
	private static final String STOCK_PLUGIN_NAME = "Opponent Information";

	@Inject
	private Client client;

	@Inject
	private CombatVitalsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NPCManager npcManager;

	@Inject
	private HiscoreManager hiscoreManager;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private CombatVitalsPanelOverlay panelOverlay;

	@Inject
	private CombatVitalsOverheadOverlay overheadOverlay;

	/** Replaced wholesale each tick, never mutated, so the overlay thread sees a consistent view. */
	@Getter
	private volatile Readout readout;

	/** Your own health. Exact, because the client knows it — never recovered. */
	@Getter
	private volatile Readout selfReadout;

	private Actor opponent;
	private Instant interactionEnded;
	private HiscoreEndpoint hiscoreEndpoint = HiscoreEndpoint.NORMAL;
	private Plugin stockPlugin;

	@Provides
	CombatVitalsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CombatVitalsConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(panelOverlay);
		overlayManager.add(overheadOverlay);

		stockPlugin = pluginManager.getPlugins().stream()
			.filter(p -> STOCK_PLUGIN_NAME.equals(p.getName()))
			.findFirst()
			.orElse(null);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(panelOverlay);
		overlayManager.remove(overheadOverlay);

		readout = null;
		selfReadout = null;
		opponent = null;
		interactionEnded = null;
		stockPlugin = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGED_IN:
				hiscoreEndpoint = HiscoreEndpoint.fromWorldTypes(client.getWorldType());
				break;
			case LOGIN_SCREEN:
			case HOPPING:
				opponent = null;
				interactionEnded = null;
				readout = null;
				selfReadout = null;
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		// The single gate the whole compliance argument rests on: this plugin
		// only ever tracks the target the user themselves engaged.
		if (event.getSource() != client.getLocalPlayer())
		{
			return;
		}

		final Actor target = event.getTarget();
		if (target != null)
		{
			opponent = target;
			interactionEnded = null;
		}
		else
		{
			// Keep the opponent: the health bar lingers after combat and the
			// readout should too. The timeout below retires it.
			interactionEnded = Instant.now();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		expireOpponent();
		readout = buildReadout();
		selfReadout = buildSelfReadout();
	}

	private void expireOpponent()
	{
		if (opponent == null || interactionEnded == null)
		{
			return;
		}

		final Player self = client.getLocalPlayer();
		if (self != null && self.getInteracting() != null)
		{
			return;
		}

		final Duration timeout = Duration.ofSeconds(Math.max(1, config.opponentTimeout()));
		if (Duration.between(interactionEnded, Instant.now()).compareTo(timeout) > 0)
		{
			opponent = null;
			interactionEnded = null;
		}
	}

	private Readout buildReadout()
	{
		final Actor actor = opponent;
		if (actor == null || actor.getName() == null)
		{
			return null;
		}

		final int scale = actor.getHealthScale();
		final int ratio = actor.getHealthRatio();

		// A despawned actor keeps a stale scale after its ratio has gone.
		if (scale <= 0 || ratio < 0)
		{
			return null;
		}

		final boolean npc = actor instanceof NPC;
		if (npc ? !config.showForNpcs() : !config.showForPlayers())
		{
			return null;
		}

		if (config.hideWhenHpHud() && hasHpHud(actor))
		{
			return null;
		}

		String name = Text.removeTags(actor.getName());
		int maxHealth = -1;
		HiscoreResult hiscore = null;

		if (npc)
		{
			final NPC target = (NPC) actor;
			final NPCComposition composition = target.getTransformedComposition();
			if (composition != null)
			{
				final String longName = composition.getStringValue(ParamID.NPC_HP_NAME);
				if (longName != null && !longName.isEmpty())
				{
					name = longName;
				}
			}

			final Integer health = npcManager.getHealth(target.getId());
			if (health != null)
			{
				maxHealth = health;
			}
		}
		else if (config.showPlayerHitpoints() || config.showStatComparison())
		{
			// One lookup per opponent, in direct response to the user engaging
			// them. HiscoreManager returns null until its cache is warm and
			// refreshes off the client thread, so this never blocks and never
			// repeats a request. The comparison reads this same result.
			hiscore = hiscoreManager.lookupAsync(name, hiscoreEndpoint);

			if (hiscore != null && config.showPlayerHitpoints())
			{
				final net.runelite.client.hiscore.Skill hitpoints =
					hiscore.getSkill(HiscoreSkill.HITPOINTS);

				// An unranked player comes back non-positive. Leaving maxHealth
				// unknown degrades to a percentage rather than a wrong number.
				if (hitpoints != null && hitpoints.getLevel() > 0)
				{
					maxHealth = hitpoints.getLevel();
				}
			}
		}

		final HealthRecovery.Range range = maxHealth > 0
			? HealthRecovery.recover(ratio, scale, maxHealth)
			: null;

		return new Readout(actor, name, ratio, scale, maxHealth, range, npc, -1, hiscore);
	}

	/**
	 * Your own health, taken from the hitpoints orb rather than inverted from a
	 * health bar.
	 *
	 * The client knows this number exactly. Running it through the recovery
	 * would print a guess in place of a fact, which would be absurd on its own
	 * terms and would undermine the one claim this plugin actually makes.
	 *
	 * Only while engaged: a permanent readout over your own head is clutter,
	 * and the orb already covers the out-of-combat case.
	 */
	private Readout buildSelfReadout()
	{
		if (!config.showOwnHealth() || opponent == null)
		{
			return null;
		}

		final Player self = client.getLocalPlayer();
		if (self == null || self.getName() == null)
		{
			return null;
		}

		final int current = client.getBoostedSkillLevel(Skill.HITPOINTS);
		final int max = client.getRealSkillLevel(Skill.HITPOINTS);
		if (max <= 0)
		{
			return null;
		}

		return new Readout(self, Text.removeTags(self.getName()), -1, -1, max, null, false, current, null);
	}

	/** Mirrors the base client: NPC only, and false for players by definition. */
	private boolean hasHpHud(Actor actor)
	{
		if (!(actor instanceof NPC) || client.getVarbitValue(VarbitID.HPBAR_HUD_BOSS_DISABLED) != 0)
		{
			return false;
		}

		final NPC npc = (NPC) actor;
		final int hudNpcId = client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
		return hudNpcId != -1
			&& npc.getComposition() != null
			&& hudNpcId == npc.getComposition().getId();
	}

	/** True when the stock plugin is drawing its own panel in the same corner. */
	boolean stockPluginEnabled()
	{
		return stockPlugin != null && pluginManager.isPluginEnabled(stockPlugin);
	}

	/** Immutable snapshot of everything the overlays need for one tick. */
	@Getter
	static final class Readout
	{
		private final Actor actor;
		private final String name;
		private final int ratio;
		private final int scale;
		private final int maxHealth;
		private final HealthRecovery.Range range;
		private final boolean npc;

		/** Known exactly, or -1 when it can only be recovered from the bar. */
		private final int exactHealth;

		/** The one cached hiscores result, shared by the readout and comparison. */
		private final HiscoreResult hiscore;

		Readout(Actor actor, String name, int ratio, int scale, int maxHealth,
			HealthRecovery.Range range, boolean npc, int exactHealth, HiscoreResult hiscore)
		{
			this.actor = actor;
			this.name = name;
			this.ratio = ratio;
			this.scale = scale;
			this.maxHealth = maxHealth;
			this.range = range;
			this.npc = npc;
			this.exactHealth = exactHealth;
			this.hiscore = hiscore;
		}
	}
}

